import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] d = new long[(int) n];
        for (int i = 0; i < d.length; i++) d[i] = Long.parseLong(next());

        if (m * k > n) {
            System.out.println(-1);
        } else {
            long lo = Long.MAX_VALUE, hi = 0;
            for (int i = 0; i < n; i++) {
                lo = Math.min(lo, d[i]);
                hi = Math.max(hi, d[i]);
            }
            while (lo < hi) {
                long mid = (lo + hi) / 2, count = 0, run = 0;
                for (int i = 0; i < n; i++) {
                    if (d[i] <= mid) {
                        run++;
                        if (run == k) {
                            count++;
                            run = 0;
                        }
                    } else {
                        run = 0;
                    }
                }
                if (count >= m) hi = mid;
                else lo = mid + 1;
            }
            System.out.println(lo);
        }
    }
}
